      examGoldenRule: 'Златно правило за ДЗИ по Химия: Запомни мнемоничната двойка: РЕДУКТОРЪТ ОТДАВА електрони и се ОКИСЛЯВА (СО расте ↑), а ОКИСЛИТЕЛЯТ ПРИЕМА електрони и се РЕДУЦИРА (СО намалява ↓)! И внимавай: при реакция на метал с концентрирана H₂SO₄ или с HNO₃ НИКОГА не се отделя водород (H₂), защото окислител там не е H⁺, а S⁺⁶ или N⁺⁵!',
