        { label: 'Методически стандарт за 6.00 (МОН)', value: 'На матура по Немски език винаги проверявай глагола в края на подчиненото изречение след „weil“, „dass“ и „obwohl“, както и избора между „haben“ и „sein“ в Perfekt (глаголите за движение и промяна на състоянието като gehen, fahren, fliegen, bleiben, sein, werden образуват Perfekt със SEIN!). На Френски и Испански следи за задължителния Subjonctif / Subjuntivo след изрази за необходимост и емоция!' }
