        'Аналогова и Цифрова схемотехника: Полупроводниковият диод пропуска ток само в права посока (изправители Grez). Транзисторът (BJT и MOSFET) работи като усилвател на сигнал в активен режим или като електронен ключ (насищане/запушване) в цифровите схеми. Универсални логически елементи са NAND (И-НЕ) и NOR (ИЛИ-НЕ).',
        'Микроконтролери, Сензори и Мехатроника (11.–12. клас ДИППК): Мехатронната система интегрира механика, електроника, сензори и управляващ софтуер (микроконтролер или индустриален контролер PLC). Аналоговите сигнали от температурни и оптични сензори се преобразуват в цифров код чрез АЦП (Аналогово-цифров преобразувател), а управлението на постояннотокови двигатели и сервомеханизми се извършва чрез ШИМ (PWM — широчинно-импулсна модулация).',
